import SwiftUI
import UIKit

// MARK: - Color Namespace

extension Color {
    static let gjuha = GjuhaColors()
}

/// Semantic colour roles for Gjuha.
///
/// Every token is a Named Color in `Palette.xcassets` with four appearances
/// (light, dark, and the increased-contrast variant of each), generated by
/// `Scripts/gen_colors.py`. That script measures every foreground/background
/// pair it ships and refuses to write a set that falls below 4.5:1, so a token
/// used in its documented role is legible by construction.
///
/// Two role distinctions matter when picking one:
///
/// - **Fill vs on-surface text.** `accent`, `success`, `error`, `warning`,
///   `streak` and `xp` are *fills*: a shape behind a foreground. The matching
///   `…Strong` token is the one to use for text or an icon drawn *on* a surface.
///   Gold text on `surface` measures 1.76:1; `xpStrong` measures 5.24:1.
/// - **What goes on a fill.** `onAccent` (white) for `accent`, `streak`,
///   `success` and `error`. `onWarning` (near-black) for `warning` and `xp`,
///   which stay bright rather than being deepened into brown.
struct GjuhaColors {
    // MARK: Brand

    /// Primary action fill. Carries ``onAccent``.
    let accent = Color("Accent")
    /// Accent as text or an icon on a surface.
    let accentStrong = Color("AccentStrong")
    /// Light tint of the accent, for selected rows and soft backgrounds.
    let accentSubtle = Color("AccentSubtle")

    // MARK: Background hierarchy

    let background = Color("Background")
    let surface = Color("Surface")
    let surfaceSecondary = Color("SurfaceSecondary")

    // MARK: Text

    let textPrimary = Color("TextPrimary")
    let textSecondary = Color("TextSecondary")
    let textTertiary = Color("TextTertiary")

    // MARK: State

    /// Success fill. Carries ``onAccent``.
    let success = Color("Success")
    /// Success as text or an icon on a surface.
    let successStrong = Color("SuccessStrong")
    /// Warning fill, deliberately bright. Carries ``onWarning``.
    let warning = Color("Warning")
    /// Warning as text or an icon on a surface.
    let warningStrong = Color("WarningStrong")
    /// Error fill. Carries ``onAccent``.
    let error = Color("Error")
    /// Error as text or an icon on a surface.
    let errorStrong = Color("ErrorStrong")

    // MARK: Gamification

    /// Streak fill. Carries ``onAccent``.
    let streak = Color("Streak")
    /// Streak as text or an icon on a surface, such as the flame and its count.
    let streakStrong = Color("StreakStrong")
    /// XP fill, deliberately bright gold. Carries ``onWarning``.
    let xp = Color("XP")
    /// XP as text or an icon on a surface, such as the star and its count.
    let xpStrong = Color("XPStrong")

    // MARK: Separators, edges and overlay fills

    /// Opaque divider and control border.
    let border = Color("Border")
    /// The edge of a glass card or a tappable surface. Inverts with the
    /// appearance, so unlike a hardcoded white overlay it stays visible in
    /// light mode.
    let hairline = Color("Hairline")
    /// The tint laid over a material inside a glass card.
    let glassTint = Color("GlassTint")
    /// The unfilled part of a progress bar, ring or meter.
    let track = Color("Track")
    /// Background of a small capsule chip.
    let chipFill = Color("ChipFill")
    /// Background of an unselected, tappable option row.
    let controlFill = Color("ControlFill")

    // MARK: Foreground on a fill

    /// Foreground on ``accent``, ``streak``, ``success`` and ``error``.
    let onAccent = Color("OnAccent")
    /// Foreground on ``warning`` and ``xp``.
    let onWarning = Color("OnWarning")
}

// MARK: - Fallback Color Literals (for previews without asset catalog)

extension Color {
    static var gjuhaAccentFallback: Color { Color(red: 0.87, green: 0.26, blue: 0.21) }
    static var gjuhaBackgroundFallback: Color { Color(UIColor.systemBackground) }
    static var gjuhaSurfaceFallback: Color { Color(UIColor.secondarySystemBackground) }
}

extension View {
    /// Constrains content to a comfortable single column reading width and centers
    /// it, so wide screens (iPad, landscape) do not stretch the single column
    /// learning UI edge to edge. On iPhone the cap is wider than the screen, so it is
    /// a no op. Apply to a screen's content, never to its full bleed background.
    func gjuhaReadableWidth(_ maxWidth: CGFloat = 620) -> some View {
        frame(maxWidth: maxWidth)
            .frame(maxWidth: .infinity)
    }
}
